const nowYear = new Date().getFullYear();
const data = {
  patterns: [
    { id: 'wolt', name: 'Wolt', type: 'częsty', count: 8, sum: 428.4, amount: null, threshold: '4 × / miesiąc', excess: 84.0, status: '' },
    { id: 'netflix', name: 'Netflix', type: 'stały', count: 1, sum: 55, amount: 55, threshold: '55,00 zł', excess: 0, status: 'zmiana kwoty' },
    { id: 'sklep', name: 'Sklep osiedlowy', type: 'częsty', count: 11, sum: 348.6, amount: null, threshold: '8 × / miesiąc', excess: 61.2, status: '' },
    { id: 'paliwo', name: 'Stacja paliw', type: 'częsty', count: 4, sum: 298.2, amount: null, threshold: '—', excess: 0, status: 'nowy' },
    { id: 'cloud', name: 'CloudBox', type: 'stały', count: 1, sum: 39.99, amount: 39.99, threshold: '39,99 zł', excess: 0, status: '' }, { id: 'excluded-coffee', name: 'Coffee Corner', type: 'częsty', count: 6, sum: 96, amount: null, threshold: '—', excess: 0, status: 'wykluczony', excluded: true }
  ],
  months: [
    { label: 'paź 25', value: 72 }, { label: 'lis 25', value: 98 }, { label: 'gru 25', value: 142 },
    { label: 'sty 26', value: 116 }, { label: 'lut 26', value: 181 }, { label: 'mar 26', value: 148 },
    { label: 'kwi 26', value: 242 }, { label: 'maj 26', value: 284, current: true }
  ],
  transactions: [
    ['25.05.2026', 'WOLT*WARSAW', 72.40, true], ['22.05.2026', 'WOLT*WARSAW', 48.00, true],
    ['18.05.2026', 'WOLT*WARSAW', 39.90, false], ['11.05.2026', 'WOLT*WARSAW', 56.30, false],
    ['06.05.2026', 'WOLT*WARSAW', 44.00, false], ['02.05.2026', 'WOLT*WARSAW', 33.20, false]
  ]
};
let demoMode = false;
const monthForms = { 'sty 2026':'w styczniu', 'lut 2026':'w lutym', 'mar 2026':'w marcu', 'kwi 2026':'w kwietniu', 'maj 2026':'w maju', 'cze 2026':'w czerwcu', 'lip 2026':'w lipcu', 'sie 2026':'w sierpniu', 'wrz 2026':'we wrześniu', 'paź 2026':'w październiku', 'lis 2026':'w listopadzie', 'gru 2026':'w grudniu', 'gru-2025':'w grudniu 2025', 'maj':'w maju', 'kwi':'w kwietniu', 'mar':'w marcu' };
const monthIn = value => monthForms[value] || `w ${value}`;
const pluralPL = (n, forms) => { const v=Math.abs(Number(n)); const d=v%10, h=v%100; return v===1?forms[0]:(d>=2&&d<=4&&!(h>=12&&h<=14)?forms[1]:forms[2]); };
const money = value => `${Number(value).toLocaleString('pl-PL', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} zł`;
const mark = (className = 'brand-mark', light = false) => `<svg class="${className}" viewBox="0 0 32 32" aria-hidden="true"><path fill="${light ? 'var(--rytm-paper)' : 'currentColor'}" fill-rule="evenodd" d="M5 29V3h13l9 9-8 8 9 9h-8l-9-9v9zm6-21v8h5l4-4-4-4z"/></svg>`;
const icon = (name, size = 18) => `<svg class="ui-icon" width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true"><use href="assets/icons/ui/ui.svg#${name}"/></svg>`;
const brand = (light = false) => `<a class="brand" href="#/">${mark('brand-mark', light)}<span>Rytm</span></a>`;
const footer = () => `<footer class="footer container"><span>© ${nowYear} Rytm. Spokojnie o pieniądzach.</span><span><a class="footer-forwho" href="#/for-who">Dla kogo</a><a href="#">Prywatność</a><a href="#">Kontakt</a></span></footer>`;
const header = () => `<header class="site-header container">${brand()}<nav class="nav"><a href="#/how-it-works">Jak działa</a><a href="#/for-who">Dla kogo</a><a class="btn btn-ghost" href="#/login">Zaloguj się</a><a class="btn btn-primary" href="#/register">Zacznij</a></nav></header>`;
const badge = (label, kind = '') => `<span class="badge ${kind}">${label}</span>`;
const toast = (message, kind = 'success') => `<div class="toast ${kind}" role="status">${icon(kind === 'error' ? 'warning' : kind === 'info' ? 'info' : 'success', 16)}<span>${message}</span><button aria-label="Zamknij" onclick="this.parentElement.remove()">${icon('close', 15)}</button></div>`;
const sideLink = (href, label, ico, active = false) => `<a class="${active ? 'active' : ''}" href="${href}">${icon(ico, 17)}<span>${label}</span></a>`;
const mobileNav = active => `<nav class="mobile-nav" aria-label="Nawigacja aplikacji">${sideLink('#/home', 'Przegląd', 'overview', active === 'home')}${sideLink('#/patterns', 'Wzorce', 'patterns', active === 'patterns')}${sideLink('#/fixed', 'Stałe', 'fixed', active === 'fixed')}${sideLink('#/imports', 'Importy', 'import', active === 'imports')}${sideLink('#/settings', 'Konto', 'settings', active === 'settings')}</nav>`;
const appHeader = () => `<header class="dash-header">${brand()}<div class="dash-user"><span class="muted">maj 2026</span></div></header>`;
const sidebar = active => `<aside class="side"><div class="side-label">Widok</div>${sideLink('#/home', 'Przegląd', 'overview', active === 'home')}${sideLink('#/patterns', 'Wzorce wydatków', 'patterns', active === 'patterns')}${sideLink('#/fixed', 'Koszty stałe', 'fixed', active === 'fixed')}<div class="side-label">Dane</div>${sideLink('#/imports', 'Importy CSV', 'import', active === 'imports')}<div class="side-bottom">${sideLink('#/settings', 'Ustawienia', 'settings', active === 'settings')}</div></aside>`;
const appShell = (active, content) => `<div class="dash-shell">${appHeader()}${demoMode ? '<div class="demo-notice">Wspólne konto demo — dodawanie i cofanie importów, zmiana hasła oraz usunięcie konta są wyłączone.</div>' : ''}<div class="dash-body">${sidebar(active)}<main class="dash-main">${content}</main></div>${mobileNav(active)}</div>`;

function landing() { return `<div class="screen"><div class="container">${header()}</div><main><section class="hero container"><div><div class="eyebrow">Spokojnie o pieniądzach</div><h1>Pieniądze uciekają w <em>rytmie.</em><br/>Rytm ten rytm pokazuje.</h1><p>Wgraj wyciąg bankowy i zobacz, które wydatki wracają zbyt często. Bez oceniania. Z jasną granicą, którą ustawiasz sam.</p><div class="hero-actions"><a class="btn btn-primary" href="#/register">Zobacz swój rytm <span>↗</span></a><a class="btn btn-ghost" href="#/how-it-works">Jak to działa?</a></div><div class="hero-note">Darmowy start · dane zostają u Ciebie</div></div><div class="hero-card"><div class="mini-top"><span>Twój miesiąc</span><span>maj 2026</span></div><div class="mini-total">3 842,60 zł</div><div class="mini-sub">wydatki rozpoznane</div><div class="bars"><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar accent"></i><i class="bar accent"></i></div><div class="rhythm-row"><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r accent"></i><i class="rhythm-r accent"></i></div></div></section><section class="section container"><div class="section-head"><div><div class="eyebrow">Bez arkusza</div><h2>Trzy kroki do jasności.</h2></div><span class="muted">Wystarczy jeden wieczór w miesiącu.</span></div><div class="three-cols"><article class="feature"><h3>01 — Wgraj CSV</h3><p>Wrzuć wyciąg z banku. Rytm rozpozna sprzedawców i powtarzające się kwoty.</p></article><article class="feature"><h3>02 — Ustaw granicę</h3><p>Sam decydujesz, ile kaw, dostaw lub subskrypcji mieści się w Twoim miesiącu.</p></article><article class="feature"><h3>03 — Zobacz ponad progiem</h3><p>Nadwyżka trafia do widoku „ponad progiem w tym miesiącu”. Bez wstydu, z konkretem.</p></article></div></section><section class="cta-band"><div class="container"><h2>Zobacz, gdzie cicho<br/>ucieka pieniądz.</h2><a class="btn btn-amber" href="#/register">Utwórz konto</a></div></section></main>${footer()}</div>`; }
function howItWorks() { return `<div class="screen"><div class="container">${header()}</div><main><section class="sub-hero container"><div><div class="eyebrow">Jak działa Rytm</div><h1>Najpierw wzorzec.<br/><em>Potem decyzja.</em></h1><p>Rytm porządkuje powtarzalne transakcje, żebyś raz w miesiącu widział to, co zwykle ginie w historii konta.</p><a class="btn btn-primary" href="#/register">Zacznij od swojego CSV <span>↗</span></a></div><div class="sequence-card"><div class="sequence-caption">Jedna granica, wiele powrotów</div><div class="sequence-track"><span class="seq active"></span><span class="seq active"></span><span class="seq active"></span><i></i><span class="seq over"></span><span class="seq over"></span></div><div class="sequence-labels"><span>Twój próg</span><b>Ponad próg</b></div></div></section><section class="section container"><div class="section-head"><div><div class="eyebrow">Od pliku do obrazu</div><h2>Trzy spokojne kroki.</h2></div><span class="muted">Bez ręcznego kategoryzowania.</span></div><div class="process-grid"><article class="process-card"><span class="process-number">01</span><h3>Wgraj wyciąg</h3><p>Wybierz plik CSV z banku. Rytm czyta datę, sprzedawcę i kwotę, a potem grupuje podobne transakcje.</p><div class="process-line"></div><small>Masz kontrolę nad plikiem</small></article><article class="process-card"><span class="process-number">02</span><h3>Rozpoznaj rytm</h3><p>Stałe koszty i częste zakupy układają się w sekwencje. Widzisz, co wraca co miesiąc, a nie przypadkowy dzień.</p><div class="process-line"></div><small>Wzorzec zamiast szumu</small></article><article class="process-card"><span class="process-number">03</span><h3>Ustaw granicę</h3><p>Próg jest Twój. Rytm zaznacza dopiero kolejne powtórzenia, a ich suma trafia do „ponad progiem w tym miesiącu”.</p><div class="process-line amber"></div><small>Bez oceniania, z konkretem</small></article></div></section><section class="explain-band"><div class="container explain-grid"><div><div class="eyebrow">Co zobaczysz</div><h2>Nie jeden duży wydatek.<br/>Cały jego rytm.</h2></div><div class="explain-list"><div><b>Stałe koszty</b><span>Ta sama usługa, podobna kwota — od razu widać podwyżkę albo nową pozycję.</span></div><div><b>Częste zakupy</b><span>Ten sam sprzedawca niezależnie od kwoty — dostawy, kawa, małe decyzje.</span></div><div><b>Ponad próg</b><span>Rytm nie mówi, co masz robić. Pokazuje miejsce, w którym możesz zdecydować.</span></div></div></div></section><section class="cta-band"><div class="container"><h2>Twój miesiąc ma<br/>swój rytm.</h2><a class="btn btn-amber" href="#/register">Zobacz go</a></div></section></main>${footer()}</div>`; }
function forWho() { return `<div class="screen"><div class="container">${header()}</div><main><section class="sub-hero audience-hero container"><div><div class="eyebrow">Dla kogo jest Rytm</div><h1>Dla osoby, która chce<br/><em>wiedzieć bez liczenia.</em></h1><p>Masz dwa konta, kilka subskrypcji i zero ochoty na kolejny arkusz. Rytm daje Ci jeden spokojny moment prawdy w miesiącu.</p><div class="hero-actions"><a class="btn btn-primary" href="#/register">Sprawdź swój rytm <span>↗</span></a><a class="btn btn-ghost" href="#/how-it-works">Zobacz jak działa</a></div></div><div class="audience-note"><span class="audience-mark">R</span><p>„Nie chcę budżetu<br/>na każdy dzień.<br/><strong>Chcę widzieć wzorce.”</strong></p></div></section><section class="section container"><div class="section-head"><div><div class="eyebrow">Brzmi znajomo?</div><h2>Rytm pasuje do Twojego tempa.</h2></div></div><div class="audience-grid"><article class="audience-card"><span class="card-index">A</span><h3>Pracujesz i ogarniasz dużo</h3><p>Nie potrzebujesz kolejnego systemu do prowadzenia. Potrzebujesz krótkiego, prawdziwego obrazu.</p><a href="#/register">Raz w miesiącu <span>↗</span></a></article><article class="audience-card"><span class="card-index">B</span><h3>Masz wydatki, które wracają</h3><p>Subskrypcje, jedzenie z dowozem, kawa po drodze. Rytm pokaże częstotliwość bez moralizowania.</p><a href="#/register">Zobacz powroty <span>↗</span></a></article><article class="audience-card"><span class="card-index">C</span><h3>Chcesz ustawić własną granicę</h3><p>Nie chodzi o zakaz. Chodzi o moment, w którym nadwyżka staje się widoczna i możesz coś z nią zrobić.</p><a href="#/register">Ustaw swój próg <span>↗</span></a></article></div></section><section class="quote-band"><div class="container"><div class="eyebrow">To nie jest aplikacja do perfekcji</div><h2>To jest aplikacja do<br/><em>większej jasności.</em></h2><p>Rytm zostawia miejsce na normalne życie. Pomaga tylko zauważyć, kiedy małe decyzje zaczynają się powtarzać.</p></div></section><section class="cta-band"><div class="container"><h2>Wystarczy jeden<br/>spokojny wieczór.</h2><a class="btn btn-amber" href="#/register">Utwórz konto</a></div></section></main>${footer()}</div>`; }
function auth(mode) { const reg = mode === 'register'; if (mode === 'reset') return resetPage(); return `<div class="auth-shell"><aside class="auth-visual">${brand(true)}<div class="auth-copy"><div class="eyebrow" style="color:var(--rytm-excess)">Twój rytm</div><h1>${reg ? 'Zacznij widzieć więcej.' : 'Wróć do swojego rytmu.'}</h1><p>${reg ? 'Jedno konto, jeden spokojny widok Twoich wydatków.' : 'Twoje wzorce wydatków czekają na kolejny miesiąc.'}</p></div></aside><main class="auth-form-wrap"><form class="auth-form" onsubmit="event.preventDefault(); ${reg ? "location.hash='#/confirm-email'" : "document.getElementById('authError').hidden=false"}"><div class="eyebrow">${reg ? 'Nowe konto' : 'Witaj ponownie'}</div><h1>${reg ? 'Utwórz konto' : 'Zaloguj się'}</h1><p>${reg ? 'Zacznij od adresu e-mail. Resztę ustawisz później.' : 'Wróć do spokojnego widoku swoich wydatków.'}</p><div id="authError" class="inline-alert error" hidden>${icon('warning', 16)}<span>Nie rozpoznaliśmy tego e-maila i hasła. Spróbuj ponownie.</span></div>${reg ? '<div class="field"><label for="name">Imię <span class="optional">opcjonalne</span></label><input id="name" placeholder="np. Ola" /></div>' : ''}<div class="field"><label for="email">E-mail</label><input id="email" type="email" placeholder="ty@przyklad.pl" required /></div><div class="field"><label for="password">Hasło</label><input id="password" type="password" placeholder="••••••••" required /></div>${reg ? '<div class="form-row"><span>Zakładając konto akceptujesz regulamin.</span></div>' : '<div class="form-row"><label><input type="checkbox"/> Zapamiętaj mnie</label><a href="#/reset">Nie pamiętam hasła</a></div>'}<button class="btn btn-primary" type="submit">${reg ? 'Utwórz konto' : 'Zaloguj się'} <span>↗</span></button><div class="auth-footer">${reg ? 'Masz już konto?' : 'Nie masz jeszcze konta?'} <a href="${reg ? '#/login' : '#/register'}">${reg ? 'Zaloguj się' : 'Utwórz je'}</a></div></form></main></div>`; }
function resetPage() { return `<div class="auth-shell"><aside class="auth-visual">${brand(true)}<div class="auth-copy"><div class="eyebrow" style="color:var(--rytm-excess)">Spokojnie</div><h1>Hasło można ustawić na nowo.</h1><p>Wyślemy Ci prostą instrukcję na adres przypisany do konta.</p></div></aside><main class="auth-form-wrap"><form class="auth-form" onsubmit="event.preventDefault();this.innerHTML='<div class=eyebrow>Sprawdź skrzynkę</div><h1>Link jest w drodze.</h1><p>Jeśli konto istnieje, wysłaliśmy instrukcję zmiany hasła.</p><a class=\"btn btn-primary\" href=\"#/login\">Wróć do logowania</a>'"><div class="eyebrow">Nie pamiętam hasła</div><h1>Odzyskaj dostęp.</h1><p>Podaj e-mail, którego używasz w Rytmie.</p><div class="field"><label for="reset-email">E-mail</label><input id="reset-email" type="email" placeholder="ty@przyklad.pl" required /></div><button class="btn btn-primary" type="submit">Wyślij instrukcję <span>↗</span></button><div class="auth-footer"><a href="#/login">Wróć do logowania</a></div></form></main></div>`; }

function trendChart() {
 const max=Math.max(1,...data.months.map(m=>m.value));
 const bars=data.months.map((m,i)=>`<div class="trend-column"><span class="trend-value">${money(m.value)}</span><i class="tbar ${m.value===0?'zero':''}" style="height:${m.value===0?'2px':Math.max(8,m.value/max*100)+'%'}" role="img" aria-label="${m.label}: ${money(m.value)} ponad próg"></i><span class="trend-month">${m.label}</span></div>`).join('');
 return `<div class="trend monthly-trend" role="group" aria-label="Miesięczna suma ponad progiem">${bars}</div><div class="legend"><span><i class="dot"></i> suma ponad progiem</span><span class="trend-zero-note">Cienka kreska oznacza 0,00 zł</span><span class="trend-no-threshold" title="Brak progu: nie ustawiono granicy dla wzorca.">Brak progu</span></div>`;
}

function dashboard(empty=false,showName=true) {
 if(empty) return appShell('home',`<div class="dash-title"><div><div class="eyebrow">Przegląd miesiąca</div><h1>Zacznij od pierwszego importu.</h1><p>Rytm pokaże Ci wzorce, kiedy dostanie pierwszy wyciąg.</p></div></div><section class="empty-dashboard panel"><img src="assets/illustrations/rytm-pusty-stan-jasny.svg" alt="Dokument czekający na import"/><h2>Nie masz jeszcze żadnego importu.</h2><p>Wgraj jeden plik CSV z wyciągu bankowego. Przed importem wybierzesz rachunek i zobaczysz zakres danych.</p><a class="btn btn-primary" href="#/imports/new">Wgraj CSV</a></section>`);
 const month='maj'; return appShell('home',`<div class="dash-title"><div><div class="eyebrow">Przegląd miesiąca</div><h1>${showName?'Dzień dobry, Olu.':'Dzień dobry.'}</h1><p>${showName?'Oto rytm Twoich wydatków w maju.':`Twój ${month} w jednym spokojnym widoku.`}</p></div><a class="btn btn-primary" href="#/imports/new">+ Wgraj CSV</a></div><div class="stats stats-single"><article class="stat-card accent"><div class="stat-label">Ponad progiem w tym miesiącu</div><div class="stat-value">284,40 zł</div><div class="stat-foot">+42,20 zł względem kwietnia</div></article></div><section class="panel dashboard-trend"><div class="panel-title"><h2>Ponad progiem</h2><span>miesięcznie · wszystkie dane</span></div>${trendChart()}</section><section class="panel dashboard-fixed"><div class="panel-title"><h2>Koszty stałe</h2><a class="text-link" href="#/fixed">Zobacz zmiany</a></div><div class="fixed-summary-row"><span>Podrożały</span><strong>2 koszty</strong></div><div class="fixed-summary-row"><span>Nowe</span><strong>1 koszt</strong></div></section>`);
}

function patternRows(list) { return list.map(p=>`<tr data-name="${p.name.toLowerCase()}" data-sum="${p.sum}" data-count="${p.count}"><td><a class="table-name" href="#/patterns/${p.id}"><span class="merchant-mark" aria-hidden="true">${p.name[0]}</span><span>${p.name}</span></a></td><td>${badge(p.type,p.type==='stały'?'fixed':'frequent')}</td><td>${p.count}</td><td>${p.type==='stały'?money(p.amount||p.sum):'—'}</td><td>${money(p.sum)}</td><td>${p.threshold}</td><td>${p.excess?`<span class="excess-value">${money(p.excess)}</span>`:'—'} ${p.status?badge(p.status,p.status==='nowy'?'new':'changed'):''}</td><td><a class="icon-button" href="#/patterns/${p.id}" aria-label="Otwórz wzorzec">${icon('arrow',16)}</a></td></tr>`).join(''); }
function patterns(empty=false) { if(empty)return emptyView('patterns'); const visible=data.patterns.filter(p=>!p.excluded); const shown=visible.slice(0,3); return appShell('patterns',`<div class="dash-title"><div><div class="eyebrow">Wzorce wydatków</div><h1>To, co wraca.</h1><p>Każdy sprzedawca ma jeden typ. Możesz zmienić go w dowolnym momencie.</p></div><a class="btn btn-primary" href="#/imports/new">+ Wgraj CSV</a></div><div class="toolbar"><label class="search-field">${icon('search',16)}<input id="patternSearch" placeholder="Szukaj sprzedawcy" /></label><label class="select-field">${icon('sort',16)}<select id="patternSort"><option value="sum">Sortuj: suma</option><option value="count">Sortuj: liczba</option><option value="name">Sortuj: nazwa</option></select></label></div><section class="panel table-panel"><div class="table-wrap"><table id="patternsTable"><thead><tr><th>Sprzedawca</th><th>Typ</th><th>Wystąpienia</th><th>Kwota</th><th>Suma</th><th>Próg</th><th>Ponad progiem</th><th></th></tr></thead><tbody>${patternRows(shown)}</tbody></table></div><div class="table-foot"><span id="patternCount">${visible.length} ${pluralPL(visible.length,['wzorzec','wzorce','wzorców'])} · wszystkie miesiące</span>${visible.length>shown.length?'<button id="showMorePatterns" class="btn btn-ghost" onclick="showMorePatterns()">Pokaż więcej</button>':''}</div></section><section class="excluded-section"><button class="excluded-toggle" aria-expanded="false" onclick="toggleExcluded(this)">${icon('arrow',14)} Wykluczone <span>1 wzorzec</span></button><div class="excluded-list panel"><div class="list-item"><div class="merchant"><span class="merchant-mark" aria-hidden="true">C</span><div><div class="item-name">Coffee Corner</div><div class="item-meta">Wykluczony z analizy</div></div></div><button class="text-button" onclick="restorePattern()">Przywróć</button></div></div></section>`); }


function thresholdEditor(p) { const no=p.threshold==='—'; return `<div class="threshold-editor"><div class="threshold-switch"><button class="threshold-option active">${p.type==='stały'?'Akceptowana kwota':'Liczba na miesiąc'}</button>${p.type==='częsty'?'<button class="threshold-option">Suma na miesiąc</button>':''}</div><div class="threshold-fields"><label><span>${p.type==='stały'?'Kwota':'Liczba wystąpień'}</span><div class="input-suffix"><input id="thresholdValue" type="number" min="0.01" step="0.01" value="${no?'':p.type==='stały'?'55':'4'}" placeholder="—"/><b>${p.type==='stały'?'zł':'×'}</b></div></label></div><div id="thresholdMessage" class="inline-alert error" hidden></div><p class="threshold-note">${no?'Ustaw próg, aby Rytm mógł oznaczać kolejne wystąpienia jako ponad próg.':'Po przekroczeniu granicy kolejne wystąpienia zostaną oznaczone etykietą „ponad próg”.'}</p><div class="threshold-actions"><button class="btn btn-primary" onclick="saveThreshold()">${no?'Ustaw próg':'Zapisz próg'}</button>${!no?'<button class="text-button" onclick="showToast(\'Próg usunięty.\',\'info\')">Usuń próg</button>':''}</div></div>`; }

function patternDetail(id) {
 const p=data.patterns.find(x=>x.id===id);
 if(!p) return appShell('patterns',`<section class="panel view-empty"><h1>Nie znaleziono wzorca.</h1><p>Mógł zniknąć po cofnięciu importu.</p><a class="btn btn-primary" href="#/patterns">Wróć do wzorców</a></section>`);
 const month=new URLSearchParams(location.hash.split('?')[1]||'').get('month')||'maj 2026'; const noOccurrences=month.startsWith('gru');
 const detailRows=noOccurrences?[]:data.transactions;
 const overCount=p.excess&&p.type==='częsty'?Math.max(1,p.count-4):0; const withinCount=p.count-overCount; const sequence=noOccurrences?'':Array.from({length:p.count},(_,i)=>`<span class="seq ${i>=withinCount&&overCount?'over':''}" aria-hidden="true"></span>`).join('');
 return appShell('patterns',`${p.excluded?`<div class="inline-alert info excluded-banner">${icon('info',16)}<span>Wykluczony z analizy</span><button class="text-button" onclick="restorePattern()">Przywróć</button></div>`:''}<div class="detail-top"><a class="back-link" href="#/patterns">${icon('arrow-left',15)} Wróć do wzorców</a><div class="detail-actions"><button class="btn btn-ghost" onclick="openModal('patternActions','${p.id}')">${icon('more',16)} Akcje</button></div></div><section class="detail-heading"><div><div class="eyebrow">${badge(p.type,p.type==='stały'?'fixed':'frequent')} wzorzec</div><h1>${p.name}</h1><p>${p.type==='stały'?'Sprzedawca o stałej, powtarzalnej kwocie.':'Sprzedawca, który wraca niezależnie od kwoty.'}</p></div><div class="detail-total"><span>Suma ${monthIn(month)}</span><strong>${noOccurrences?'0,00 zł':money(p.sum)}</strong><small>${noOccurrences?'0 wystąpień':`${p.count} ${pluralPL(p.count,['wystąpienie','wystąpienia','wystąpień'])}`}</small></div></section><section class="detail-grid"><div class="panel"><div class="panel-title"><h2>Próg wzorca</h2><span>${p.threshold==='—'?'brak ustawionego progu':'aktywny'}</span></div>${thresholdEditor(p)}</div><div class="panel"><div class="panel-title"><h2>Wystąpienia w miesiącu</h2><label class="select-field small"><select onchange="location.hash='#/patterns/${p.id}?month='+encodeURIComponent(this.value)"><option ${month==='maj 2026'?'selected':''}>maj 2026</option><option ${month==='kwi 2026'?'selected':''}>kwi 2026</option><option ${month==='gru 2025'?'selected':''}>gru 2025</option></select></label></div>${noOccurrences?`<div class="no-occurrences">${icon('info',18)}<span>Brak wystąpień w tym miesiącu.</span></div>`:`<div class="sequence-large" role="img" aria-label="${withinCount} ${pluralPL(withinCount,['wystąpienie','wystąpienia','wystąpień'])} w ramach progu, ${overCount} ${pluralPL(overCount,['wystąpienie','wystąpienia','wystąpień'])} ponad próg">${sequence}</div><div class="sequence-labels"><span>W ramach progu</span><b>Ponad próg</b></div>`}</div></section><section class="panel transactions-panel"><div class="panel-title"><h2>Transakcje z wyciągu</h2><span>opis surowy · kwota</span></div>${noOccurrences?'<p class="muted">Brak transakcji do pokazania w wybranym miesiącu.</p>':`<div class="list">${detailRows.map(t=>`<div class="list-item"><div><div class="item-name">${t[0]}</div><div class="item-meta">${t[1]}</div></div><div class="transaction-right"><strong>${money(t[2])}</strong>${t[3]?badge('ponad próg','excess'):''}</div></div>`).join('')}</div>`}${p.mergedVariants?`<div class="merged-variants"><h3>Połączone nazwy</h3><ul>${p.mergedVariants.map(v=>`<li>${v}</li>`).join('')}</ul><button class="text-button" onclick="undoMerge('${p.id}')">Cofnij scalenie</button></div>`:''}</section>`);
}

function fixedCosts(state='') { const noMonth=state==='no-month', error=state==='error'; return appShell('fixed',`<div class="dash-title"><div><div class="eyebrow">Koszty stałe</div><h1>Co zmieniło się samo?</h1><p>Rytm porównuje miesiące kalendarzowe i pokazuje różnice.</p></div></div>${error?`<div class="inline-alert error">${icon('warning',16)}<span>Nie udało się wczytać kosztów stałych. Odśwież widok.</span></div>`:noMonth?`<div class="info-panel">Brak poprzedniego miesiąca do porównania.</div>`:''}<section class="fixed-section"><div class="section-label"><h2>Zmieniły kwotę</h2><span>2 pozycje</span></div><div class="fixed-list panel"><div class="fixed-row"><div class="merchant"><span class="merchant-mark">N</span><div><strong>Netflix</strong><small>20.05.2026 · poprzednio 49,00 zł</small></div></div><div class="fixed-change"><span>55,00 zł</span><b class="increase">+6,00 zł · wzrost</b></div></div><div class="fixed-row"><div class="merchant"><span class="merchant-mark">C</span><div><strong>CloudBox</strong><small>02.05.2026 · poprzednio 44,99 zł</small></div></div><div class="fixed-change"><span>39,99 zł</span><b class="decrease">−5,00 zł · spadek</b></div></div></div></section><section class="fixed-section"><div class="section-label"><h2>Nowe w tym miesiącu</h2><span>1 pozycja</span></div><div class="fixed-list panel"><div class="fixed-row"><div class="merchant"><span class="merchant-mark">M</span><div><strong>MusicFlow</strong><small>pierwsze wystąpienie · 15.05.2026</small></div></div><div class="fixed-change"><span>19,99 zł</span>${badge('nowy','new')}</div></div></div></section><section class="fixed-section"><div class="section-label"><h2>Bez zmian</h2><span>2 pozycje</span></div><div class="fixed-list panel compact"><div class="fixed-row"><div class="merchant"><span class="merchant-mark">A</span><strong>Adobe</strong></div><span>79,00 zł</span></div><div class="fixed-row"><div class="merchant"><span class="merchant-mark">H</span><strong>Hosting</strong></div><span>29,00 zł</span></div></div></section><section class="fixed-empty-states">${state==='no-changes'?'<div class="info-panel">W tym miesiącu nie zmieniły się żadne koszty stałe.</div>':''}${state==='no-new'?'<div class="info-panel">Nie pojawiły się nowe koszty stałe.</div>':''}</section>`); }

function emptyView(kind) { var c={patterns:['Wzorce pojawią się po pierwszym imporcie.','Tutaj zobaczysz sprzedawców, którzy wracają w Twoich wydatkach.'],fixed:['Koszty stałe pojawią się po pierwszym imporcie.','Tutaj zobaczysz subskrypcje i opłaty, które zmieniły kwotę lub pojawiły się po raz pierwszy.'],imports:['Nie masz jeszcze żadnego importu.','Tutaj znajdziesz historię wgranych wyciągów i ich zakresy dat.']}[kind]; var label=kind==='patterns'?'Wzorce wydatków':kind==='fixed'?'Koszty stałe':'Importy CSV'; return appShell(kind,'<div class="dash-title"><div><div class="eyebrow">'+label+'</div><h1>'+c[0]+'</h1><p>'+c[1]+'</p></div></div><section class="view-empty panel"><div class="empty-mark">'+icon(kind==='imports'?'import':kind==='fixed'?'fixed':'patterns',28)+'</div><h2>Wgraj pierwszy wyciąg</h2><p>Jeden plik CSV wystarczy, aby Rytm mógł rozpoznać Twój rytm wydatków.</p><a class="btn btn-primary" href="#/imports/new">Wgraj CSV <span>↗</span></a></section>'); }
function resetNew(state='') { const visual=`<aside class="auth-visual">${brand(true)}<div class="auth-copy"><div class="eyebrow" style="color:var(--rytm-excess)">Spokojnie</div><h1>Hasło można ustawić na nowo.</h1><p>Wybierz nowe hasło, aby wrócić do swojego rytmu.</p></div></aside>`; if(state==='expired') return `<div class="auth-shell">${visual}<main class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">Link wygasł</div><h1>Ten link już wygasł.</h1><p>Dla bezpieczeństwa link do zmiany hasła działa przez ograniczony czas.</p><div class="inline-alert error">${icon('warning',16)}<span>Wyślij nowy link, aby kontynuować.</span></div><a class="btn btn-primary" href="#/reset">Wyślij nowy link</a></div></main></div>`; if(state==='success') return `<div class="auth-shell">${visual}<main class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">Gotowe</div><h1>Hasło zostało zmienione.</h1><p>Możesz teraz zalogować się do swojego rytmu.</p><a class="btn btn-primary" href="#/login">Zaloguj się</a></div></main></div>`; return `<div class="auth-shell">${visual}<main class="auth-form-wrap"><form class="auth-form" onsubmit="event.preventDefault();validateNewPassword()"><div class="eyebrow">Nowe hasło</div><h1>Ustaw nowe hasło.</h1><p>Hasło musi mieć co najmniej 6 znaków.</p><div class="field"><label for="newPassword">Nowe hasło</label><div class="password-control"><input id="newPassword" type="password" minlength="6" required/><button type="button" class="password-toggle" onclick="togglePassword('newPassword',this)">Pokaż</button></div></div><div class="field"><label for="repeatPassword">Powtórz hasło</label><div class="password-control"><input id="repeatPassword" type="password" minlength="6" required/><button type="button" class="password-toggle" onclick="togglePassword('repeatPassword',this)">Pokaż</button></div></div><div id="newPasswordMessage" class="inline-alert error" hidden></div><button class="btn btn-primary" type="submit">Zapisz nowe hasło</button><div class="auth-footer"><a href="#/login">Wróć do logowania</a></div></form></main></div>`; }
function confirmEmail() { return `<div class="auth-shell"><aside class="auth-visual">${brand(true)}<div class="auth-copy"><div class="eyebrow" style="color:var(--rytm-excess)">Jeszcze jeden krok</div><h1>Twój rytm zaczyna się od jasności.</h1><p>Potwierdź adres e-mail, aby dokończyć tworzenie konta.</p></div></aside><main class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">Sprawdź skrzynkę</div><h1>Link jest w drodze.</h1><p>Wysłaliśmy link aktywacyjny na podany adres e-mail. Kliknij go, aby dokończyć rejestrację.</p><div class="inline-alert info">${icon('info',16)}<span>Nie widzisz wiadomości? Sprawdź folder spam.</span></div><button id="resendButton" class="btn btn-ghost" onclick="startResend()">Wyślij ponownie</button><div class="auth-footer"><a href="#/login">Wróć do logowania</a></div></div></main></div>`; }
function startResend() { const b=document.getElementById('resendButton');if(!b)return;let n=60;b.disabled=true;b.textContent=`Wyślij ponownie za ${n} s`;const timer=setInterval(()=>{n-=1;b.textContent=n?`Wyślij ponownie za ${n} s`:'Wyślij ponownie';if(!n){clearInterval(timer);b.disabled=false;}},1000); }
function validateNewPassword() { const a=document.getElementById('newPassword'),b=document.getElementById('repeatPassword'),m=document.getElementById('newPasswordMessage'); if(a.value.length<6){m.hidden=false;m.textContent='Hasło musi mieć co najmniej 6 znaków.';return;} if(a.value!==b.value){m.hidden=false;m.textContent='Hasła muszą być takie same.';return;}location.hash='#/reset/new?success=1'; }

function imports() { const q=new URLSearchParams(location.hash.split('?')[1]||''); const status=q.get('status'); return appShell('imports',`<div class="dash-title"><div><div class="eyebrow">Importy CSV</div><h1>Twoje źródła danych.</h1><p>Każdy import możesz cofnąć. Plik CSV nie jest przechowywany po imporcie.</p></div><a class="btn btn-primary" href="#/imports/new">+ Nowy import</a></div>${status?`<div class="inline-alert ${status==='deleted'?'success':'error'}">${icon(status==='deleted'?'success':'warning',16)}<span>${status==='deleted'?'Import usunięty.':status==='not-found'?'Nie znaleziono importu.':'Nie udało się usunąć importu. Spróbuj ponownie.'}</span></div>`:''}<section class="panel import-table"><div class="table-wrap"><table><thead><tr><th>Data importu</th><th>Bank</th><th>Rachunek</th><th>Zakres dat</th><th>Obciążenia</th><th></th></tr></thead><tbody><tr><td>28.05.2026</td><td>ING Bank Śląski</td><td>Konto główne · •• 4821</td><td>01.05–28.05.2026</td><td>64</td><td><button class="text-button danger" onclick="openModal('deleteImport')">Usuń import</button></td></tr><tr><td>30.04.2026</td><td>Santander Bank Polska</td><td>Rachunek · •• 1094</td><td>01.04–30.04.2026</td><td>71</td><td><button class="text-button danger" onclick="openModal('deleteImport')">Usuń import</button></td></tr></tbody></table></div></section>`); }

function importsNew(state='') { const errors={unknown:'Nieznany format pliku. Obsługujemy ING Bank Śląski i Santander Bank Polska.',currency:'Waluta inna niż PLN. Wybierz plik rachunku prowadzonego w PLN.',empty:'Brak obciążeń. Ten plik zawiera tylko wpływy lub jest pusty.',large:'Plik przekracza limit 5 MB. Wybierz mniejszy plik.',many:'Plik zawiera ponad 5 000 obciążeń. Podziel wyciąg na mniejsze zakresy.',inconsistent:'Plik jest niespójny: liczba wierszy lub daty nie zgadzają się z deklarowanym zakresem. Pobierz wyciąg ponownie.'}; return appShell('imports',`<div class="dash-title"><div><div class="eyebrow">Nowy import</div><h1>Dodaj wyciąg.</h1><p>Wybierzesz jeden rachunek z pliku. Import obejmuje tylko obciążenia.</p></div><a class="back-link" href="#/imports">${icon('arrow-left',15)} Wróć do importów</a></div>${demoMode?'<div class="inline-alert info">'+icon('info',16)+'<span>Na wspólnym koncie demo dodawanie importów jest wyłączone.</span></div>':''}<div class="import-flow"><div class="flow-step active"><b>1</b><span>Plik CSV</span></div><div class="flow-line"></div><div class="flow-step"><b>2</b><span>Rachunek</span></div><div class="flow-line"></div><div class="flow-step"><b>3</b><span>Podsumowanie</span></div></div><section class="panel upload-zone"><div class="upload-symbol">${icon('upload',28)}</div><h2>Upuść plik CSV tutaj</h2><p>Obsługujemy wyciągi ING Bank Śląski i Santander Bank Polska w PLN.</p><button class="btn btn-primary" ${demoMode?'disabled':''} onclick="document.getElementById('csvInput').click()">Wybierz plik</button><input id="csvInput" type="file" hidden accept=".csv" onchange="document.getElementById('uploadState').innerHTML=uploadReady()"/><div id="uploadState"></div></section><section class="import-errors">${state&&errors[state]?`<div class="inline-alert error"><span>${errors[state]} <button class="text-button" onclick="location.hash='#/imports/new'">Wybierz inny plik</button></span></div>`:''}</section><div class="prototype-error-links">Podgląd stanów: ${Object.keys(errors).map(k=>`<a href="#/imports/new?error=${k}">${k}</a>`).join(' · ')}</div>`); }

function uploadReady() { return `<div class="upload-ready">${icon('success', 16)} <span>wyciag-maj-2026.csv · rozpoznano format ING</span><button class="text-button" onclick="location.hash='#/imports/new/account'">Dalej ${icon('arrow', 14)}</button></div>`; }
function importAccount() { return appShell('imports',`<div class="dash-title"><div><div class="eyebrow">Nowy import · krok 2 z 3</div><h1>Wybierz rachunek.</h1><p>Ten plik zawiera rachunki. Właściciel konta nie jest wyświetlany.</p></div></div><section class="panel account-picker"><label class="account-option selected"><input type="radio" name="account" checked/><span><strong>Konto główne · •• 4821</strong><small>ING Bank Śląski · 64 transakcje</small></span><b>wybrane</b></label><label class="account-option"><input type="radio" name="account"/><span><strong>Rachunek · •• 1094</strong><small>Santander Bank Polska · 71 transakcji</small></span></label><div class="flow-actions"><a class="btn btn-ghost" href="#/imports/new">Wstecz</a><a class="btn btn-primary" href="#/imports/new/summary">Dalej</a></div></section>`); }

function importSummary() { const q=new URLSearchParams(location.hash.split('?')[1]||''); const overlap=q.get('error')==='overlap'; const n=64; const debitWord=pluralPL(n,['obciążenie','obciążenia','obciążeń']); const transactionWord=pluralPL(n,['transakcja','transakcje','transakcji']); return appShell('imports',`<div class="dash-title"><div><div class="eyebrow">Nowy import · krok 3 z 3</div><h1>Sprawdź przed importem.</h1><p>Import obejmuje jeden rachunek i tylko obciążenia.</p></div></div>${overlap?`<section class="panel summary-panel"><div class="summary-grid"><div><span>Rachunek</span><strong>ING · Konto główne · •• 4821</strong></div><div><span>Zakres dat</span><strong>01.05–28.05.2026</strong></div><div><span>Obciążenia do importu</span><strong>64 transakcje</strong></div><div><span>Pominięte wpływy / zwroty</span><strong>12 transakcji</strong></div></div><div class="inline-alert error">${icon('warning',16)}<span>Ten zakres nachodzi na istniejący import: <a href="#/imports">1 marca – 31 maja 2026</a>. Wybierz inny plik albo wróć do importów.</span></div><div class="flow-actions"><a class="btn btn-ghost" href="#/imports/new">Wybierz inny plik</a><a class="btn btn-ghost" href="#/imports">Wróć do importów</a></div></section>`:`<section class="panel summary-panel"><div class="summary-grid"><div><span>Bank</span><strong>Santander Bank Polska</strong></div><div><span>Rachunek</span><strong>Rachunek · •• 1094</strong></div><div><span>Zakres dat</span><strong>01.05–28.05.2026</strong></div><div><span>Obciążenia do importu</span><strong>${n} ${transactionWord}</strong></div></div><div class="flow-actions"><a class="btn btn-ghost" href="#/imports/new/account">Wstecz</a><button class="btn btn-primary" ${demoMode?'disabled':''} onclick="startImport()">Importuj ${n} ${debitWord}</button></div>${demoMode?'<div class="inline-alert info">'+icon('info',16)+'<span>Na wspólnym koncie demo dodawanie importów jest wyłączone.</span></div>':''}<div id="processing" class="progress-wrap" hidden><span>Importowanie…</span><div class="progress"><i></i></div></div></section>`}`); }

function importResult() { const q=new URLSearchParams(location.hash.split('?')[1]||''); const status=q.get('status')||'success'; const n=64; const debitWord=pluralPL(n,['obciążenie','obciążenia','obciążeń']); const transactionWord=pluralPL(n,['transakcja','transakcje','transakcji']); if(status==='error') return appShell('imports',`<section class="panel result-state"><div class="inline-alert error">${icon('warning',16)}<span>Nie udało się zapisać importu. Spróbuj ponownie.</span></div><a class="btn btn-primary" href="#/imports/new">Wróć do importu</a></section>`); if(status==='not-found') return appShell('imports',`<section class="panel result-state"><h1>Nie znaleziono importu.</h1><a class="btn btn-ghost" href="#/imports">Wróć do importów</a></section>`); if(status==='waiting') return appShell('imports',`<section class="panel result-state"><span class="progress-wrap">Importowanie…<i class="progress"><i></i></i></span></section>`); return appShell('imports',`<div class="result-layout"><div class="result-icon">${icon('success',30)}</div><div class="eyebrow">Import gotowy</div><h1>Dodaliśmy ${n} ${debitWord}.</h1><section class="panel result-meta"><div><span>Bank</span><strong>Santander Bank Polska</strong></div><div><span>Rachunek</span><strong>Rachunek · •• 1094</strong></div><div><span>Zakres dat</span><strong>01.05–28.05.2026</strong></div><div><span>Transakcje</span><strong>${n} ${transactionWord}</strong></div></section><div class="hero-actions"><a class="btn btn-primary" href="#/patterns">Zobacz wzorce</a><a class="btn btn-ghost" href="#/home">Przejdź do przeglądu</a></div></div>`); }

function settings() { const q=new URLSearchParams(location.hash.split('?')[1]||''); const state=q.get('state')||''; const notice=state==='password-success'?['success','Hasło zostało zmienione.']:state==='password-invalid'?['error','Obecne hasło jest nieprawidłowe.']:state==='error'?['error','Nie udało się zapisać zmian. Spróbuj ponownie.']:state==='delete-error'?['error','Nie udało się usunąć konta. Spróbuj ponownie.']:null; return appShell('settings',`<div class="dash-title"><div><div class="eyebrow">Ustawienia / konto</div><h1>Twoje konto.</h1><p>Sprawdź dane i ustawienia prywatności.</p></div></div>${notice?`<div class="inline-alert ${notice[0]}">${icon(notice[0]==='success'?'success':'warning',16)}<span>${notice[1]}</span></div>`:''}<section class="panel settings-panel"><div class="panel-title"><h2>Dane logowania</h2></div><div class="settings-row"><span>E-mail</span><strong>ola@example.com</strong><button class="btn btn-ghost">Zmień</button></div><div class="settings-row password-row"><span>Hasło</span><strong>••••••••</strong><button class="btn btn-ghost" onclick="togglePasswordForm()">Zmień hasło</button></div><form id="settingsPasswordForm" class="settings-password-form" onsubmit="event.preventDefault();submitPasswordChange()" hidden><div class="field"><label for="currentPassword">Obecne hasło</label><input id="currentPassword" type="password" required /></div><div class="field"><label for="settingsNewPassword">Nowe hasło</label><div class="password-control"><input id="settingsNewPassword" type="password" minlength="6" required/><button type="button" class="password-toggle" onclick="togglePassword('settingsNewPassword',this)">Pokaż</button></div></div><div class="field"><label for="repeatNewPassword">Powtórz hasło</label><input id="repeatNewPassword" type="password" minlength="6" required/></div><div class="form-actions"><button class="btn btn-primary" type="submit">Zapisz hasło</button><button class="btn btn-ghost" type="button" onclick="togglePasswordForm()">Anuluj</button></div></form><div class="settings-row"><span>Przetwarzanie danych</span><p>Plik CSV nie jest przechowywany po imporcie. Konto przechowuje wynik analizy i Twoje decyzje.</p></div><div class="settings-row logout-row"><span>Sesja</span><a class="btn btn-ghost" href="#/login">Wyloguj się</a></div></section><section class="panel danger-panel"><div><div class="eyebrow">Strefa destrukcyjna</div><h2>Usuń konto</h2><p>Usunięcie konta kasuje importy, wzorce, progi i wszystkie decyzje bez śladu.</p></div><button class="btn btn-danger" onclick="openModal('deleteAccount')">Usuń konto</button></section>`); }

function components() { return `<div class="screen"><div class="container">${header()}</div><main class="component-page container"><div class="eyebrow">Biblioteka UI</div><h1>Komponenty Rytmu.</h1><p class="muted">Przykłady stanów i zasad, które składają się na interfejs aplikacji.</p><section class="component-section"><h2>Badge i etykiety</h2><div class="component-row">${badge('stały', 'fixed')}${badge('częsty', 'frequent')}${badge('ponad próg', 'excess')}${badge('wykluczony', 'excluded')}${badge('nowy', 'new')}${badge('zmiana kwoty', 'changed')}</div></section><section class="component-section"><h2>Alerty</h2><div class="component-alerts"><div class="inline-alert success">${icon('success', 16)} Sukces — próg zapisany.</div><div class="inline-alert error">${icon('warning', 16)} Błąd — sprawdź plik CSV.</div><div class="inline-alert info">${icon('info', 16)} Informacja — trend pojawi się po 3 miesiącach.</div></div></section><section class="component-section"><h2>Formularze, skeleton, tabela</h2><div class="component-row"><label class="search-field">${icon('search', 16)}<input placeholder="Szukaj" /></label><label class="select-field"><select><option>Wybierz opcję</option><option>Stały</option><option>Częsty</option></select></label><button class="btn btn-primary">Zapisz</button><button class="btn btn-ghost" onclick="openModal('patternActions')">Otwórz dialog</button></div><div class="skeleton-demo"><i></i><i></i><i></i></div></section></main>${footer()}</div>`; }
function modal(type,patternId='wolt') { const p=data.patterns.find(x=>x.id===patternId)||data.patterns[0]; const mergeOptions=data.patterns.filter(x=>x.id!==patternId&&!x.excluded); if(type==='deleteAccount') return `<div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><button class="modal-close" onclick="closeModal()" aria-label="Zamknij">${icon('close',17)}</button><div class="eyebrow">Usunięcie konta</div><h2 id="modalTitle">Usunąć konto bez śladu?</h2><p>Ta decyzja usunie wszystkie importy, wzorce i progi.</p><div class="field"><label for="deleteCurrentPassword">Obecne hasło</label><input id="deleteCurrentPassword" type="password" required oninput="document.getElementById('confirmDeleteButton').disabled=this.value.trim()===('')||document.getElementById('confirmDelete').value!=='USUŃ'||demoMode" ${demoMode?'disabled':''}/></div><p>Wpisz <strong>USUŃ</strong>, aby potwierdzić.</p><input id="confirmDelete" class="modal-input" placeholder="USUŃ" oninput="document.getElementById('confirmDeleteButton').disabled=this.value!=='USUŃ'||!document.getElementById('deleteCurrentPassword').value.trim()||demoMode"/><button id="confirmDeleteButton" class="btn btn-danger" disabled onclick="deleteAccountAction()">Usuń konto</button>${demoMode?`<div class="inline-alert info">${icon('info',16)}<span>Na wspólnym koncie demo usunięcie konta jest wyłączone.</span></div>`:''}</div></div>`;
 if(type==='deleteImport') { const range='01.05–31.05.2026'; return `<div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><button class="modal-close" onclick="closeModal()" aria-label="Zamknij">${icon('close',17)}</button><div class="eyebrow">Cofnij import</div><h2 id="modalTitle">Usunąć import z zakresu ${range}?</h2><p>Wzorce wykryte w tym imporcie zostaną przeliczone.</p>${demoMode?`<div class="inline-alert info">${icon('info',16)}<span>Na wspólnym koncie demo cofanie importów jest wyłączone.</span></div>`:''}<button class="btn btn-danger" ${demoMode?'disabled':''} onclick="deleteImportAction()">Usuń import</button></div></div>`; }
 if(type==='merge') return `<div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><button class="modal-close" onclick="closeModal()" aria-label="Zamknij">${icon('close',17)}</button><div class="eyebrow">Akcje na wzorcu</div><h2 id="modalTitle">Scal wzorce</h2><p>Wybierz sprzedawcę, którego transakcje mają należeć do „${p.name}”.</p>${mergeOptions.length?`<label class="field"><span>Wzorzec</span><select id="mergeTarget">${mergeOptions.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label><div class="inline-alert error" id="mergeError" hidden>Nie można scalić tych wzorców.</div><button class="btn btn-primary" onclick="saveMerge('${p.id}')">Scal wzorce</button>`:`<div class="info-panel">Nie ma innych wzorców do scalenia.</div>`}</div></div>`;
 if(type==='mergeEmpty') return `<div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><button class="modal-close" onclick="closeModal()" aria-label="Zamknij">${icon('close',17)}</button><div class="eyebrow">Akcje na wzorcu</div><h2 id="modalTitle">Scal wzorce</h2><p>Wybierz sprzedawcę, którego transakcje mają należeć do wzorca.</p><div class="info-panel">Nie ma innych wzorców do scalenia.</div><button class="btn btn-ghost" disabled>Scal wzorce</button></div></div>`; if(type==='rename') return `<div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><button class="modal-close" onclick="closeModal()" aria-label="Zamknij">${icon('close',17)}</button><div class="eyebrow">Akcje na wzorcu</div><h2 id="modalTitle">Zmień nazwę wzorca</h2><label class="field"><span>Nowa nazwa</span><input id="renamePattern" maxlength="61" placeholder="${p.name}"/></label><div id="renameError" class="field-error" hidden>Nazwa może mieć maksymalnie 60 znaków.</div><button class="btn btn-primary" onclick="saveRename('${p.id}')">Zapisz</button></div></div>`;
 return `<div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><button class="modal-close" onclick="closeModal()" aria-label="Zamknij">${icon('close',17)}</button><div class="eyebrow">Akcje na wzorcu</div><h2 id="modalTitle">Zarządzaj wzorcem.</h2><p>Decyzje dotyczą wszystkich kolejnych miesięcy. Możesz je później odwrócić w ustawieniach wzorca.</p><div class="modal-actions"><button class="btn btn-ghost" onclick="openModal('merge','${p.id}')">${icon('merge',16)} Scal z…</button><button class="btn btn-ghost" onclick="changePatternType('${p.id}')">${icon('switch',16)} Zmień typ</button><button class="btn btn-ghost" onclick="openModal('rename','${p.id}')">${icon('edit',16)} Zmień nazwę</button><button class="btn btn-ghost" onclick="excludePattern('${p.id}')">${icon('exclude',16)} Wyklucz z analizy</button></div><div class="merged-variants"><h3>Połączone nazwy</h3><ul>${(p.mergedVariants||['WOLT*WARSAW']).map(v=>`<li>${v}</li>`).join('')}</ul><button class="text-button" onclick="undoMerge('${p.id}')">Cofnij scalenie</button></div></div></div>`; }

function openModal(type,patternId='wolt') { document.getElementById('modal')?.remove(); document.body.insertAdjacentHTML('beforeend',modal(type,patternId)); }

function closeModal() { document.getElementById('modal')?.remove(); }
function showToast(message, kind) { document.body.insertAdjacentHTML('beforeend', toast(message, kind)); setTimeout(() => document.querySelector('.toast')?.remove(), 3400); }
function bindInteractions() { const search=document.getElementById('patternSearch'),sort=document.getElementById('patternSort'); const update=()=>{const term=(search?.value||'').toLowerCase();let list=data.patterns.filter(p=>!p.excluded&&p.name.toLowerCase().includes(term));const key=sort?.value||'sum';list.sort((a,b)=>key==='name'?a.name.localeCompare(b.name):b[key]-a[key]);const tbody=document.querySelector('#patternsTable tbody');if(tbody)tbody.innerHTML=patternRows(list.slice(0,3));};search?.addEventListener('input',update);sort?.addEventListener('change',update); const confirmDelete=document.getElementById('confirmDelete'),button=document.getElementById('confirmDeleteButton');if(confirmDelete&&button)button.disabled=confirmDelete.value!=='USUŃ'||!document.getElementById('deleteCurrentPassword')?.value.trim()||demoMode; }

function showMorePatterns() { const tbody=document.querySelector('#patternsTable tbody'); if(!tbody)return; tbody.innerHTML=patternRows(data.patterns.filter(p=>!p.excluded)); document.getElementById('showMorePatterns')?.remove(); }
function toggleExcluded(button) { const section=button.parentElement,open=section.classList.toggle('open');button.setAttribute('aria-expanded',String(open)); }
function startImport() { const button=document.querySelector('.summary-panel .btn-primary'); if(demoMode){showToast('Na wspólnym koncie demo dodawanie importów jest wyłączone.','info');return;} button.disabled=true;button.textContent='Importowanie…';document.getElementById('processing').hidden=false;setTimeout(()=>location.hash='#/imports/result',650); }
function deleteImportAction() { if(demoMode){showToast('Na wspólnym koncie demo cofanie importów jest wyłączone.','info');return;} const b=document.querySelector('#modal .btn-danger'); if(b){b.disabled=true;b.textContent='Usuwanie…';} setTimeout(()=>{closeModal();location.hash='#/imports?status=deleted';},450); }
function deleteAccountAction() { if(!document.getElementById('deleteCurrentPassword')?.value.trim()||document.getElementById('confirmDelete')?.value!=='USUŃ')return; if(demoMode){showToast('Na wspólnym koncie demo usunięcie konta jest wyłączone.','info');return;} location.hash='#/settings?state=delete-error';closeModal(); }
function togglePasswordForm() { const f=document.getElementById('settingsPasswordForm');if(f)f.hidden=!f.hidden; }
function submitPasswordChange() { if(demoMode){showToast('Na wspólnym koncie demo zmiana hasła jest wyłączona.','info');return;} const a=document.getElementById('settingsNewPassword'),b=document.getElementById('repeatNewPassword');if(a.value.length<6){a.setCustomValidity('Hasło musi mieć co najmniej 6 znaków.');a.reportValidity();return;}if(a.value!==b.value){b.setCustomValidity('Hasła muszą być takie same.');b.reportValidity();return;}location.hash='#/settings?state=password-success'; }
function saveThreshold() { const input=document.getElementById('thresholdValue'),message=document.getElementById('thresholdMessage'); if(!input||Number(input.value)<=0){if(message){message.hidden=false;message.textContent='Wpisz próg większy od zera.';}return;} const button=document.querySelector('.threshold-actions .btn');button.disabled=true;button.textContent='Zapisywanie…';setTimeout(()=>{if(message){message.hidden=false;message.classList.add('success');message.textContent='Nie udało się zapisać progu. Spróbuj ponownie.';}button.disabled=false;button.textContent='Zapisz próg';},450); }
function saveMerge(id) { const target=document.getElementById('mergeTarget');if(!target)return; const p=data.patterns.find(x=>x.id===id);if(p){p.mergedVariants=p.mergedVariants||[];p.mergedVariants.push(data.patterns.find(x=>x.id===target.value)?.name||'');}closeModal();showToast('Wzorce scalone.','success'); }
function saveRename(id) { const input=document.getElementById('renamePattern');if(!input)return;if(input.value.length>60){document.getElementById('renameError').hidden=false;return;}const p=data.patterns.find(x=>x.id===id);if(p&&input.value.trim())p.name=input.value.trim();closeModal();showToast('Nazwa wzorca zmieniona.','success'); }
function changePatternType(id) { const p=data.patterns.find(x=>x.id===id);if(p)p.type=p.type==='stały'?'częsty':'stały';closeModal();showToast('Typ wzorca zmieniony.','success'); }
function excludePattern(id) { const p=data.patterns.find(x=>x.id===id);if(p)p.excluded=true;closeModal();showToast('Wzorzec wykluczony z analizy.','success'); }
function undoMerge(id) { const p=data.patterns.find(x=>x.id===id);if(p)p.mergedVariants=[];closeModal();showToast('Scalenie cofnięte.','success'); }
function restorePattern() { const p=data.patterns.find(x=>x.id==='excluded-coffee');if(p)p.excluded=false;showToast('Wzorzec przywrócony do analizy.','success'); }
function togglePassword(id,button) { var input=document.getElementById(id); if(!input)return; input.type=input.type==='password'?'text':'password'; button.textContent=input.type==='password'?'Pokaż':'Ukryj'; }
function applyDashboardState(path) { if(path==='#/home-no-name') { var h=document.querySelector('.dash-title h1'); var lead=document.querySelector('.dash-title p'); if(h) h.textContent='Dzień dobry.'; if(lead) lead.textContent='Twój maj w jednym spokojnym widoku.'; } }

function applyAuthState(path,q) { if(path==='#/login'&&q.get('confirmed')) { var f=document.querySelector('.auth-form'); if(f) f.insertAdjacentHTML('afterbegin','<div class="inline-alert success">'+icon('success',16)+'<span>E-mail potwierdzony — zaloguj się.</span></div>'); } if(path==='#/register'&&q.get('error')) { var f=document.querySelector('.auth-form'); if(f) f.insertAdjacentHTML('afterbegin','<div class="inline-alert error">'+icon('warning',16)+'<span>'+ (q.get('error')==='occupied' ? 'Ten e-mail jest już zajęty. <a href="#/login">Zaloguj się</a> lub <a href="#/reset">Nie pamiętam hasła</a>.' : 'Nie udało się utworzyć konta. Sprawdź adres e-mail i spróbuj ponownie.') +'</span></div>'); } document.querySelectorAll('.auth-form input[type=password]').forEach(function(input){ if(input.parentElement.classList.contains('password-control'))return; var wrap=document.createElement('div');wrap.className='password-control';input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);var b=document.createElement('button');b.type='button';b.className='password-toggle';b.textContent='Pokaż';b.onclick=function(){togglePassword(input.id,b);};wrap.appendChild(b); }); }
function render() { document.getElementById('modal')?.remove(); const raw=location.hash||'#/';const parts=raw.slice(1).split('?');const p='#'+parts[0];const q=new URLSearchParams(parts[1]||'');if(q.get('demo')==='1')demoMode=true; else if(p==='#/login'||p==='#/'||p==='#/register')demoMode=false;let html;
 if(p==='#/reset/new') html=resetNew(q.get('success')?'success':q.get('state')||'');
 else if(p==='#/confirm-email') html=confirmEmail();
 else if(p==='#/patterns-empty') html=emptyView('patterns'); else if(p==='#/fixed-empty')html=emptyView('fixed');else if(p==='#/imports-empty')html=emptyView('imports');
 else if(p==='#/home-no-name')html=dashboard(false,false);else if(p==='#/login'&&q.get('deleted'))html=auth('login');else if(p==='#/login'&&q.get('confirmed'))html=auth('login');else if(p==='#/register'&&q.get('error'))html=auth('register');
 else if(p==='#/login')html=auth('login');else if(p==='#/register')html=auth('register');else if(p==='#/reset')html=resetPage();else if(p==='#/home')html=dashboard();else if(p==='#/home-empty')html=dashboard(true);else if(p==='#/patterns')html=patterns();else if(p.startsWith('#/patterns/'))html=patternDetail(p.split('/')[2]);else if(p==='#/fixed')html=fixedCosts(q.get('state')||'');else if(p==='#/imports')html=imports();else if(p==='#/imports/new')html=importsNew(q.get('error')||'');else if(p==='#/imports/new/account')html=importAccount();else if(p==='#/imports/new/summary')html=importSummary();else if(p==='#/imports/result')html=importResult();else if(p==='#/settings')html=settings();else if(p==='#/components')html=components();else if(p==='#/how-it-works')html=howItWorks();else if(p==='#/for-who')html=forWho();else html=landing();
 document.getElementById('app').innerHTML=html;bindInteractions();applyAuthState(p,q);applyDashboardState(p);if(p.startsWith('#/patterns/')&&q.get('modal')){const m=q.get('modal');openModal(m==='merge-empty'?'mergeEmpty':m==='merge-error'?'merge':m==='rename-error'?'rename':'patternActions');if(m==='merge-error'){const e=document.getElementById('mergeError');if(e)e.hidden=false;}if(m==='rename-error'){const e=document.getElementById('renameError');if(e)e.hidden=false;}}if(p==='#/login'&&q.get('deleted')){const f=document.querySelector('.auth-form');if(f)f.insertAdjacentHTML('afterbegin','<div class="inline-alert success">Konto zostało usunięte. Możesz zalogować się ponownie lub utworzyć nowe konto.</div>');}window.scrollTo(0,0); }


window.addEventListener('hashchange', render);
render();
